<script setup lang="ts">import {ref} from 'vue';import {Building2,MapPin,Clock,Tag,Check,BadgeCheck} from 'lucide-vue-next';import WorkshopHeader from '../../components/WorkshopHeader.vue';import {company} from '../../data/company';import {useVintro} from '../../composables/useVintro';const {notify}=useVintro();const tab=ref('Profile');const form=ref({name:company.name,legalName:company.legalName,vat:company.vat,phone:company.phone,email:company.email});const save=()=>notify('Company settings saved')
</script>
<template><WorkshopHeader title="Company settings" subtitle="Servis Ljubljana" back="/workshop/more"/><div class="mx-auto max-w-5xl p-5 md:p-8"><div class="flex gap-2 overflow-x-auto"><button v-for="t in ['Profile','Locations','Services & brands','Price list']" @click="tab=t" class="whitespace-nowrap rounded-full px-4 py-2 text-sm font-medium" :class="tab===t?'bg-ink text-white':'border bg-white'">{{t}}</button></div><section v-if="tab==='Profile'" class="card mt-6 p-5 md:p-7"><div class="flex items-center justify-between"><div class="flex items-center gap-2"><Building2/><h2 class="section-title">Business information</h2></div><span class="flex items-center gap-1 text-xs font-semibold text-success"><BadgeCheck :size="16"/>Vintro Partner</span></div><div class="mt-6 grid gap-5 sm:grid-cols-2"><label><span class="label">Trading name</span><input v-model="form.name" class="field"/></label><label><span class="label">Legal name</span><input v-model="form.legalName" class="field"/></label><label><span class="label">VAT number</span><input v-model="form.vat" class="field nums"/></label><label><span class="label">Phone</span><input v-model="form.phone" class="field"/></label><label class="sm:col-span-2"><span class="label">Business email</span><input v-model="form.email" class="field"/></label></div><button @click="save" class="btn-primary mt-6"><Check :size="17"/>Save profile</button></section><section v-else-if="tab==='Locations'" class="mt-6 grid gap-4 md:grid-cols-2"><div v-for="l in company.locations" class="card p-5"><div class="flex items-center gap-2"><MapPin :size="18"/><h2 class="font-semibold">{{l.name}}</h2></div><p class="mt-4 text-sm text-muted">{{l.address}}</p><p class="mt-3 flex items-center gap-2 text-sm"><Clock :size="16"/>{{l.hours}}</p><p class="mt-3 text-sm">{{l.bays}} workshop bays</p><button class="btn-secondary mt-5 w-full">Edit location</button></div></section><section v-else-if="tab==='Services & brands'" class="card mt-6 p-5"><h2 class="section-title">Offered services</h2><div class="mt-4 flex flex-wrap gap-2"><button v-for="s in company.services" class="rounded-full bg-emerald-50 px-3 py-2 text-sm font-medium text-accent">✓ {{s}}</button></div><h2 class="section-title mt-8">Supported brands</h2><div class="mt-4 flex flex-wrap gap-2"><span v-for="b in company.brands" class="rounded-full bg-stone-100 px-3 py-2 text-sm">{{b}}</span></div></section><section v-else class="card mt-6 overflow-hidden"><div class="flex items-center gap-2 p-5"><Tag :size="19"/><h2 class="section-title">Location price list</h2></div><div class="divide-y border-t"><div v-for="p in company.prices" class="flex justify-between px-5 py-4 text-sm"><span>{{p[0]}}</span><strong>{{p[1]}}</strong></div></div><button class="m-5 btn-secondary">Edit prices</button></section></div></template>
